import argparse,importlib.util,json,re,hashlib
from pathlib import Path
s=importlib.util.spec_from_file_location('h',Path(__file__).with_name('reviewed-ocr.py'));h=importlib.util.module_from_spec(s);s.loader.exec_module(h)
p=argparse.ArgumentParser();p.add_argument('--cache',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();b=h.DraftBatch(a.cache,a.output)
def src(sid):
 raw=json.load(open(h.ROOT/'import/prepared'/(sid+'.json')));assert raw['sha256']==hashlib.sha256((a.cache/(sid+'.pdf')).read_bytes()).hexdigest();return raw,[p['text'] for p in raw['pages']]
def reading(pages,start,starts,corrections=()):
 t='\n'.join(pages[:2]);t=t[t.index(start):].split('Turn over')[0]
 t=h.fixes(t,corrections);parts=h.split(t,starts)
 assert h.m.clean(' '.join(parts))==h.m.clean(t), 'Reading span lost text'
 return parts
def note(start,title,items,limit='ONE WORD ONLY'):
 rows=[]
 for item in items:
  # H=bold source heading, B=source bullet, D=source dash one level deeper.
  kind,text=item[:1],item[2:];rows.append(h.row(text,0 if kind=='H' else 3 if kind=='D' else 1.5,None if kind=='H' else '–' if kind=='D' else '•',kind=='H',1.4 if kind=='H' and rows else .3))
 g=h.notes(start,13,title,rows,4);g['wordLimit']=limit;g['sourceInstructions']=g['sourceInstructions'].replace('ONE WORD ONLY',limit);return g
def tfq(page,start,end):
 # Numbered rows only; callers use this only where scan and OCR agree.
 t=page.split('NOT GIVEN if there is no information on this')[1];matches=list(re.finditer(r'(?m)^(\d+)\s+',t));assert [int(x[1]) for x in matches]==list(range(start,end+1))
 return [h.m.clean(t[x.end():matches[i+1].start() if i+1<len(matches) else len(t)]).split('IRS')[0].strip() for i,x in enumerate(matches)]
def save(job,sid,title,paras,groups,raw,corrections,subtitle=None,footnotes=None):
 b.save(job,sid,title,1,paras,groups,raw,corrections,subtitle,footnotes)

